using LocalChat;
using System.Text.Json;
int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);passed++;}void Reject(Action f,string name){try{f();}catch{Check(true,name);return;}throw new Exception("Not rejected: "+name);}
foreach(string tool in WorkspaceCore.Tools)Check(WorkspaceCore.NeedsApproval(0,tool,true),"always ask "+tool);
Check(!WorkspaceCore.NeedsApproval(1,"browser_search",false),"review allows search");Check(!WorkspaceCore.NeedsApproval(1,"make_zip",false),"review allows local ZIP");Check(WorkspaceCore.NeedsApproval(1,"copy_to_output",false),"review confirms external copy");Check(WorkspaceCore.NeedsApproval(2,"screen_capture",false),"screen stays gated separately");Check(!WorkspaceCore.NeedsApproval(2,"screen_capture",true),"explicit screen grant respected");Check(!WorkspaceCore.NeedsApproval(2,"copy_to_output",false),"workspace scope permits copy");Reject(()=>WorkspaceCore.NeedsApproval(9,"browser_read",true),"invalid permission mode rejected");
Check(WorkspaceCore.ParseTool("{\"tool\":\"browser_search\",\"query\":\"Qwen\"}")?.query=="Qwen","structured search parsed");Check(WorkspaceCore.ParseTool("```json\n{\"tool\":\"browser_read\"}\n```")?.tool=="browser_read","fenced JSON parsed");Check(WorkspaceCore.ParseTool("Обычный ответ.")==null,"normal final answer not a tool");Reject(()=>WorkspaceCore.ParseTool("{\"tool\":\"shell\",\"query\":\"del C:\\\\*\"}"),"arbitrary command tool rejected");Reject(()=>WorkspaceCore.ParseTool("{\"tool\":\"browser_read\",\"query\":null}"),"null parameters rejected");Check(WorkspaceCore.ParseTool("{broken")==null,"malformed JSON is not executed");
Check(WorkspaceCore.Quick("погугли пример C#")?.query=="пример C#","direct Russian search");Check(WorkspaceCore.Quick("сделай скриншот")?.tool=="screen_capture","direct screenshot");Check(WorkspaceCore.Quick("загрузи на флешку")?.tool=="copy_to_output","direct USB copy");Check(WorkspaceCore.Quick("дай zip")?.tool=="make_zip","direct ZIP");Check(WorkspaceCore.Quick("объясни как загрузи на флешку работает")==null,"incidental phrase not treated as command");
Check(WorkspaceCore.Quick("открой браузер")?.url=="about:blank","opening browser itself requires no Google/network request");
foreach(string q in new[]{"открой браузер я подключу тебя к тг","открой браузер, я войду в Telegram","открой браузер для телеграма","открой браузер тг","открой тг"})Check(WorkspaceCore.Quick(q)?.url=="https://web.telegram.org/k/","Telegram login intent opens Telegram, not Google: "+q);
string home=Path.Combine(Path.GetTempPath(),"nora-work-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(home);try{string src=Path.Combine(home,"src.txt");File.WriteAllText(src,"payload");string folder=Path.Combine(home,"usb");Directory.CreateDirectory(folder);string a=WorkspaceCore.CopyNew(src,folder,"result.txt"),b=WorkspaceCore.CopyNew(src,folder,"result.txt");Check(a!=b&&File.ReadAllText(a)=="payload","copy creates distinct files");Check(File.ReadAllText(src)=="payload","source unchanged");File.WriteAllText(Path.Combine(folder,"result.txt"),"old");WorkspaceCore.CopyNew(src,folder,"result.txt");Check(File.ReadAllText(Path.Combine(folder,"result.txt"))=="old","existing destination never overwritten");Reject(()=>WorkspaceCore.CopyNew(src,folder,"../escape.txt"),"copy traversal denied");Reject(()=>WorkspaceCore.CopyNew(src,folder,"..\\escape.txt"),"Windows copy traversal denied");Reject(()=>WorkspaceCore.ArtifactPath(home,"../escape"),"artifact traversal denied");Reject(()=>WorkspaceCore.ArtifactPath(home,"..\\escape"),"Windows artifact traversal denied");Check(WorkspaceCore.ArtifactPath(home,"a/b.txt").StartsWith(home+Path.DirectorySeparatorChar),"artifact remains inside root");if(!OperatingSystem.IsWindows()){string link=Path.Combine(home,"link");Directory.CreateSymbolicLink(link,folder);Reject(()=>WorkspaceCore.CopyNew(src,link,"result.txt"),"reparse/symlink destination denied");}
var m=new Message{Role="assistant",StartedAt=DateTime.UtcNow,ElapsedSeconds=12.4,Work=new(){new(){Text="ZIP создан"}},Artifacts=new(){new(){Name="example.zip",Bytes=10,Kind="zip",RelativePath="id/file.zip"}}};string path=Path.Combine(home,"message.json");Disk.Save(path,m);var restored=Disk.Read<Message>(path)!;Check(restored.Work.Count==1&&restored.Artifacts[0].Bytes==10&&restored.ElapsedSeconds==12.4,"work duration and artifacts persist");var s=new Settings();Check(s.AccessMode==0&&!s.ScreenAllowed&&!s.ToolMode,"new powers off by default");}finally{Directory.Delete(home,true);}
